def git(*args):return subprocess.check_output(['git',*args],cwd=root,text=True).strip()
def show(commit,path):return subprocess.check_output(['git','show',f'{commit}:{path}'],cwd=root,text=True)
def blob(commit,path):
    try:return subprocess.check_output(['git','rev-parse',f'{commit}:{path}'],cwd=root,text=True,stderr=subprocess.DEVNULL).strip()
    except subprocess.CalledProcessError:return None
